styles.h1:
font-size: 26px;
color: #4caf50;
margin-bottom: 8px;
letter-spacing: 0.5px;
font-weight: 600;
position: relative;
display: inline-block;

styles.h6:
color: #6b8c42;
margin-top: 1.2em;
margin-bottom: 0.5em;
font-weight: 700;
border-bottom: 1px solid #d4d9c9;
padding-bottom: 0.3em;

styles.a:
color: #4caf50;
text-decoration: none;
border-bottom: 1px dashed #c8e6c9;
transition: all 0.3s ease;

styles.ul:
background: white;
border-radius: 12px;
padding: 20px 25px;
box-shadow: 0 4px 15px rgba(0, 0, 0, 0.03);

styles.ol:
background: white;
border-radius: 12px;
padding: 20px 25px;
box-shadow: 0 4px 15px rgba(0, 0, 0, 0.03);

styles.li:
position: relative;


margin-bottom: 24px;
padding-left: 40px;
color: #555;
font-size: 15px;
border-bottom: 1px dashed #e8f5e9;
padding-bottom: 20px;

styles.blockquote:
background-color: white;
border-left: 4px solid #a5d6a7;
color: #4caf50;
border-radius: 0 12px 12px 0;
box-shadow: 0 4px 15px rgba(0, 0, 0, 0.03);
